<?php
declare(strict_types=1);require '../config/db.php';require '../config/auth.php';require_role('parishioner','login.php');$rows=$pdo->query("SELECT a.*,u.full_name publisher FROM announcements a LEFT JOIN users u ON u.id=a.published_by ORDER BY a.published_at DESC")->fetchAll();$pageTitle='Announcements.';$eyebrow='Parish News';?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Announcements</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><div class="shell"><?php include 'includes/sidebar.php'?><main class="main"><?php include 'includes/header.php'?><section data-live-scope><div class="live-filter-bar"><label class="field live-search-field">Search announcements<input class="search" type="search" data-live-search placeholder="Start typing a title, message, publisher or date..."></label><button type="button" class="btn light" data-live-clear>Clear</button><span class="live-filter-meta" data-live-count></span></div><div class="grid two" data-live-list><div class="card live-empty" data-live-empty hidden>No announcements match your search.</div><?php if(!$rows):?><div class="card"><p class="muted">No announcements have been published yet.</p></div><?php endif?><?php foreach($rows as $a):?><article class="card" data-live-item data-search="<?=e(strtolower($a['title'].' '.$a['content'].' '.($a['publisher']??'').' '.$a['published_at']))?>"><div class="eyebrow"><?=date('F j, Y',strtotime($a['published_at']))?></div><h2><?=e($a['title'])?></h2><p><?=nl2br(e($a['content']))?></p><?php if($a['publisher']):?><small class="muted">Published by <?=e($a['publisher'])?></small><?php endif?></article><?php endforeach?></div></section></main></div><script src="../assets/js/script.js"></script></body></html>
